import assert from 'node:assert/strict';
import { spawnAoeServe, type ServeHandle } from '/home/fraggle/src/agent-of-empires-git-worktrees/5052-agent-error-design/web/tests/helpers/aoeServe.ts';
import { startAcpSession } from '/home/fraggle/src/agent-of-empires-git-worktrees/5052-agent-error-design/web/tests/helpers/acp.ts';

const [binary] = process.argv.slice(2);
assert(binary?.startsWith('/'), 'absolute binary required');
process.env.AOE_E2E_BINARY = binary;
process.env.AOE_E2E_DEBUG = '1';
let serve: ServeHandle | undefined;
let stop!: () => void;
const stopped = new Promise<void>((resolve) => { stop = resolve; });
process.once('SIGTERM', stop);
process.once('SIGINT', stop);
process.once('SIGHUP', stop);
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => { if (String(chunk).trim() === 'stop') stop(); });
try {
  const started = await startAcpSession(async (options) => {
    serve = await spawnAoeServe({ ...options, workerIndex: 0, parallelIndex: 28 });
    return serve;
  }, {
    title: 'A request error keeps the native session',
    fakeAcpScript: { turns: [
      { updates: [], error: { code: -32603, message: 'CONTROLLED_REQUEST_CONNECTION_FAILURE', data: { reason: 'incoming_transport_closed' } } },
      { updates: [
        { sessionUpdate: 'wait_for_release' },
        { sessionUpdate: 'agent_message_chunk', content: { type: 'text', text: 'SECOND_EXPLICIT_REQUEST_SUCCEEDED_ON_THE_SAME_SESSION' } },
      ], stopReason: 'end_turn' },
    ] },
  });
  console.log('A_UI_SMOKE_READY', JSON.stringify({ baseUrl: started.serve.baseUrl, sessionId: started.sessionId, home: started.serve.home, binary, releasePath: started.serve.home + '/fake-acp-script.json.release' }));
  await stopped;
} finally {
  process.stdin.pause();
  if (serve) {
    await serve.stop();
    console.log('A_UI_SMOKE_CLEANUP_GREEN');
  }
}
